-- Portal (restaurant owner) authentication (003)
-- Per-user email+password login for the restaurant portal. Tokens are random
-- 256-bit values; only their SHA-256 hex digest is stored.
-- NOTE: ids are TEXT (uuid strings generated by the app), matching 001.
-- Relations are enforced by the application layer (no FK constraints).

CREATE TABLE IF NOT EXISTS portal_users (
  id TEXT PRIMARY KEY,
  email TEXT NOT NULL UNIQUE,
  password_hash TEXT NOT NULL,
  role TEXT NOT NULL DEFAULT 'owner',
  location_id TEXT NOT NULL,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS idx_portal_users_email ON portal_users(email);
CREATE INDEX IF NOT EXISTS idx_portal_users_location ON portal_users(location_id);

CREATE TABLE IF NOT EXISTS portal_tokens (
  token_hash TEXT PRIMARY KEY,
  user_id TEXT NOT NULL,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  expires_at TIMESTAMPTZ NOT NULL DEFAULT now() + interval '7 days'
);
CREATE INDEX IF NOT EXISTS idx_portal_tokens_user ON portal_tokens(user_id);
